/**
 * @file core/schema_error_text.hpp
 * @brief One valijson constraint failure, translated into plain English.
 *
 * `valijson::ValidationResults::Error::description` is generated by the
 * validator itself, in JSON-Schema-keyword vocabulary a wire caller
 * understands and a person reading a toast or a Response Viewer panel does
 * not: "Value type not permitted by 'type' constraint.", "Missing required
 * property 'x'.". Two callers show this verbatim to a person -
 * `elements/registry.cpp`'s element-config validation and
 * `schema_validation.cpp`'s response-body validation - so the translation
 * lives once, here, rather than twice.
 */

#include <nlohmann/json_fwd.hpp>

#include <optional>
#include <string>

namespace vayu::core {

/**
 * Whose schema a failure came from, which decides the vocabulary. An element
 * kind's config schema describes settings a person fills into a form; a
 * response schema describes a body, where "a setting this element has" and
 * "a number" for an integer both misname the problem (#3037).
 */
enum class SchemaErrorContext {
    ElementSettings,
    ResponseBody,
};

/**
 * valijson's own wording for one schema-constraint failure, translated into
 * plain English for the constraints this engine's own callers actually
 * trigger - `type`, `required`, `additionalProperties`, `minimum`/`maximum`,
 * `minLength`/`maxLength`, `enum`, `pattern`. Reads the failing property's
 * own declared `"title"` (and `"description"` for a `pattern` failure, which
 * names no bound of its own to restate) off @p schema at the JSON Pointer
 * the error names, and the schema's own declared bound or enum list, rather
 * than re-parsing them out of valijson's text - so the message stays correct
 * even if valijson's own phrasing changes between versions, and reads well
 * whether @p schema is one of this engine's own element config schemas
 * (which #1607 guarantees a title on every property) or an imported
 * document's response schema (which may declare none, in which case the
 * property's own JSON key is shown instead).
 *
 * @p schema is walked only through `properties` (never `$ref`, `oneOf`, or
 * an array `items`), which is the whole shape this engine's own element
 * config schemas use; a response schema reached through an unresolved `$ref`
 * degrades gracefully to the property's raw key rather than a title, and a
 * constraint outside the set above, or a description this cannot match,
 * falls back to valijson's own text rather than showing nothing.
 *
 * @p context picks the wording for what only a settings form or only a body
 * has: a property the schema does not declare, an integer, `null`, the
 * document root. A response-body message never names a setting or an element.
 */
std::string humanize_schema_error (const nlohmann::json& schema,
const std::string& error_description,
const std::string& error_json_pointer,
SchemaErrorContext context = SchemaErrorContext::ElementSettings);

/**
 * The property name valijson's `additionalProperties` failure rejected, or
 * nothing when @p error_description is another failure. valijson's error
 * location names the *object* holding the property; this is the one place the
 * property itself is recorded, so a caller that wants its own location (a
 * response failure's path) reads it from here.
 */
std::optional<std::string> unexpected_property_name (const std::string& error_description);

} // namespace vayu::core
